<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { onBeforeRouteLeave, useRouter } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import CampusEditor from '../components/CampusEditor.vue'
import { createReference, type ReferenceMetadata } from '../api/references'
import type { DocumentInput } from '../types/document'
import { limits,validationMessage } from '../editor/limits'
const router = useRouter(), value = ref<DocumentInput>({ title:'',schemaVersion:'1',content:{type:'doc',content:[]},sources:[] }), sourceType = ref('URL'), url = ref(''), description = ref(''), organization = ref(''), publishedAt = ref(''), posting = ref(false), uploading = ref(false), uploadError = ref(false), error = ref('')
const signature = computed(() => JSON.stringify({ value:value.value,sourceType:sourceType.value,url:url.value,description:description.value,organization:organization.value,publishedAt:publishedAt.value }))
const limitError=computed(()=>validationMessage(value.value,limits.value)||(sourceType.value==='URL'&&url.value.length>(limits.value?.urlCharacters??0)?'原始网页链接超过字符上限；输入已保留':''))
const baseline = signature.value; let sent = false, previous = '', key = ''
function addSource() { value.value.sources.push({sourceId:crypto.randomUUID(),url:''}) }
async function submit() { if(posting.value || uploading.value || uploadError.value) return; if(limitError.value){error.value=limitError.value;return}; posting.value = true; error.value = ''; try { const metadata: ReferenceMetadata = {sourceType:sourceType.value}; if(sourceType.value === 'URL') metadata.url = url.value; else metadata.description = description.value; if(organization.value.trim()) metadata.sourceOrganization = organization.value.trim(); if(publishedAt.value) metadata.published_at = new Date(publishedAt.value+':00+08:00').toISOString(); const payload = JSON.parse(JSON.stringify({...value.value,sourceMetadata:metadata})); const current = JSON.stringify(payload); if(current !== previous) { previous = current;key = crypto.randomUUID() }; await createReference(key,payload);sent = true;await router.replace('/references') } catch(failure) { error.value = failure instanceof Error ? failure.message : '导入未确认，当前内容仍保留' } finally { posting.value = false } }
function beforeUnload(event: BeforeUnloadEvent) { if(!sent && signature.value !== baseline) { event.preventDefault();event.returnValue = '' } }
async function leave() { if(sent || signature.value === baseline) return true; try { await ElMessageBox.confirm('当前参考材料尚未提交，确认离开？','未提交材料',{confirmButtonText:'离开',cancelButtonText:'继续填写'});return true } catch{return false} }
onBeforeRouteLeave(leave);window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false" /><div class="panel section-heading"><RouterLink to="/references">返回参考作品</RouterLink><el-button type="primary" :loading="posting" :disabled="uploading || uploadError || !!limitError" @click="submit">提交参考材料</el-button></div><section class="panel"><p class="muted">单篇导入用于参考比对，不生成发布稿。更正材料时请停用原条目后重新添加。</p><el-input v-model="value.title" :disabled="posting" aria-label="参考标题" placeholder="参考标题（必填）" class="article-title-input" /><el-alert v-if="limitError" :title="limitError" type="warning" :closable="false" /><CampusEditor v-model="value" :disabled="posting" @uploading="uploading = $event" @upload-error="uploadError = $event" /></section><section class="panel reference-source-form"><h2>材料来源</h2><label>来源类型</label><el-radio-group v-model="sourceType" :disabled="posting"><el-radio value="URL">网页来源</el-radio><el-radio value="MANUAL">人工提供</el-radio></el-radio-group><template v-if="sourceType === 'URL'"><label>原始网页链接（必填）</label><el-input v-model="url" :disabled="posting" aria-label="原始网页链接" placeholder="http/https来源链接"  /></template><template v-else><label>来源说明（必填）</label><el-input v-model="description" :disabled="posting" aria-label="材料来源说明" type="textarea" :rows="3"  /></template><label>来源组织（已知才填）</label><el-input v-model="organization" :disabled="posting" maxlength="200" aria-label="来源组织" /><label>原始发布时间（北京时间，已知才填）</label><input v-model="publishedAt" :disabled="posting" aria-label="原始发布时间" type="datetime-local" /><h2>正文补充来源</h2><div v-for="(source,index) in value.sources" :key="source.sourceId" class="source-row"><el-input v-model="source.url" :disabled="posting" placeholder="正文补充来源链接"  /><el-button :disabled="posting" @click="value.sources.splice(index,1)">删除</el-button></div><el-button :disabled="posting" @click="addSource">添加正文来源</el-button></section></template>
